window.initialImages=[{"src":"/media/images/sample.max-800x600.jpg","alt":"CarouselImage","title":"My Caption","description":""}];;document.addEventListener('alpine:init',()=>{Alpine.data('imageGallery',()=>({images:window.initialImages||[],currentIndex:0,showCarousel:false,openCarousel(index){this.currentIndex=index;this.showCarousel=true;},nextImage(){this.currentIndex=(this.currentIndex+1)%this.images.length;},prevImage(){this.currentIndex=(this.currentIndex-1+this.images.length)%this.images.length;}}));});;